                local ok, custom = pcall(function() return _getcustomasset(lf) end)
                if ok and custom then return custom end
            end
        end
    end
    return nil
end

local function resolveLogo(url)
    local urlStr = tostring(url or "")
    local isHyper = (not url or url == "" or urlStr == "136264753381080" or urlStr == "rbxassetid://136264753381080" or urlStr == "92567372646337" or urlStr == "rbxassetid://92567372646337" or urlStr:find("HYPER") or urlStr == DEFAULT_HYPER_LOGO_URL or urlStr:find("postimg%.cc") or urlStr:find("pic%.in%.th"))

    if isHyper then
        -- 1. Try local custom asset
        local custom = getHyperCustomAsset()
        if custom then return custom end

        -- 2. Try writing from embedded base64 and returning custom asset
        if _writefile then
            local data = getEmbeddedLogoData()
            if data and #data > 0 then
                pcall(function()
                    if _makefolder and _isfolder and not _isfolder("HYPER_Cache") then
                        _makefolder("HYPER_Cache")
                    end
                    _writefile("HYPER_Cache/HYPER.png", data)
                    _writefile("HYPER_Cache/HYPER-v2_3dbced53.png", data)
                end)
                if _getcustomasset then
                    local ok, c = pcall(function() return _getcustomasset("HYPER_Cache/HYPER.png") end)
                    if ok and c then return c end
                end
            end
        end

        -- 3. Try fetching from remote URL
        local remoteUrls = {
            "https://i.postimg.cc/c4VhHd3s/HYPER-v2.png",
            "https://raw.githubusercontent.com/projecthyper10-stack/HYPER-LOADER/refs/heads/main/HYPER.png"
        }
        for _, rUrl in ipairs(remoteUrls) do
            local ok, netData = pcall(function()
                if _request then
                    local res = _request({ Url = rUrl, Method = "GET" })
                    if res and (res.StatusCode == 200 or res.Success) and res.Body and #res.Body > 0 then
                        return res.Body
                    end
                end
                if game and game.HttpGet then
                    return game:HttpGet(rUrl)
                end
                return nil
            end)
            if ok and netData and #netData > 0 and _writefile and _getcustomasset then
                pcall(function()
                    if _makefolder and _isfolder and not _isfolder("HYPER_Cache") then
                        _makefolder("HYPER_Cache")
                    end
                    _writefile("HYPER_Cache/HYPER.png", netData)
                end)
                local okC, c = pcall(function() return _getcustomasset("HYPER_Cache/HYPER.png") end)
                if okC and c then return c end
            end
        end

        -- Fallback: native working Roblox asset
        return "rbxthumb://type=Asset&id=13857987062&w=420&h=420"
    end

    if urlStr:find("github%.com/.+/blob/") then
        urlStr = urlStr:gsub("github%.com/([^/]+)/([^/]+)/blob/", "raw.githubusercontent.com/%1/%2/")
    end

    if urlStr:match("^rbxassetid://") or urlStr:match("^rbxthumb://") or urlStr:match("^rbxasset://") then
        return urlStr
    end
    if tonumber(urlStr) then
        return "rbxassetid://" .. urlStr
    end

    if urlStr:match("^https?://") and _getcustomasset then
        local ext = urlStr:match("%.([%w]+)$") or "png"
        local baseName = (urlStr:match("([^/?#]+)%.") or "asset"):gsub("[^%w_-]", "")
        local filePath = "HYPER_Cache/" .. baseName .. "_" .. urlHash(urlStr) .. "." .. ext
        if _isfile and _isfile(filePath) then
            local ok, custom = pcall(function() return _getcustomasset(filePath) end)
            if ok and custom then return custom end
        end
        local ok, data = pcall(function()
            if _request then
                local res = _request({ Url = urlStr, Method = "GET" })
                if res and res.StatusCode == 200 and res.Body then return res.Body end
            end
            if game and game.HttpGet then
                return game:HttpGet(urlStr)
            end
            return nil
        end)
        if ok and data and #data > 0 and _writefile then
            pcall(function() _writefile(filePath, data) end)
            local ok2, custom = pcall(function() return _getcustomasset(filePath) end)
            if ok2 and custom then return custom end
        end
    end

    return "rbxthumb://type=Asset&id=13857987062&w=420&h=420"
end

