-- ==============================================================================
-- // Dynamic Game Registry Loader (Loads purely from Games.lua)
-- ==============================================================================
local function loadGameRegistry()
    -- 1. Local Games.lua
    if typeof(isfile) == "function" and typeof(readfile) == "function" then
        local localPaths = {
            Config.GamesConfigLocal,
            "Scripts/UI.main/Games.lua",
            "UI.main/Games.lua",
            "Scripts/Games.lua",
            "Games.lua"
        }
        for _, path in ipairs(localPaths) do
            if isfile(path) then
                local okRead, content = pcall(function() return readfile(path) end)
                if okRead and content and #content > 20 then
                    local fn = loadstring(content)
                    if fn then
                        local ok, tbl = pcall(fn)
                        if ok and type(tbl) == "table" then
                            return tbl
                        end
                    end
                end
            end
        end
    end

    -- 2. Remote Games.lua
    local remoteUrls = {
        Config.GamesConfigRemote,
        Config.GamesConfigFallbackRemote
    }
    local reqFunc = (request or http_request or (syn and syn.request) or (http and http.request))
    for _, url in ipairs(remoteUrls) do
        local ok, code = pcall(function()
            if reqFunc then
                local res = reqFunc({
                    Url = url,
                    Method = "GET",
                    Headers = {
                        ["User-Agent"] = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
                        ["Accept"] = "*/*"
                    }
                })
                if res and (res.StatusCode == 200 or res.Status == 200) and #res.Body > 20 then
                    return res.Body
                end
            end
            return game:HttpGet(url)
        end)
        if ok and code and #code > 20 then
            local fn = loadstring(code)
            if fn then
                local okRun, tbl = pcall(fn)
                if okRun and type(tbl) == "table" then
                    return tbl
                end
            end
        end
    end

    warn("[Singularity Hub] Failed to load Games.lua registry")
    return {}
end

local TargetGames = loadGameRegistry()

local function detectCurrentGame()
    local currentPlace = PlaceId
    for gameName, data in pairs(TargetGames) do
        if data.PlaceIds then
            for _, id in ipairs(data.PlaceIds) do
                if id == currentPlace then
                    return gameName, data
                end
            end
        end
    end

    -- Fallback: If map is not in the list, run Universal / UITest.lua
    if TargetGames["Universal"] then
        return "Universal", TargetGames["Universal"]
    end

    return "Universal", {
        RequiresKey = false,
        Local = "Scripts/UI.main/UITest.lua",
        Remote = "https://raw.githubusercontent.com/projecthyper10-stack/HYPER-LOADER/refs/heads/main/UI.main/UITest.lua"
    }
end

