-- ==============================================================================
local function resolveBannerAsset(url)
    local urlStr = tostring(url or "")
    if urlStr == "" then
        return resolveXinzAsset("banner")
    end

    if urlStr:find("rbxassetid://") or urlStr:find("rbxthumb://") or tonumber(urlStr) then
        if tonumber(urlStr) then return "rbxassetid://" .. tostring(urlStr) end
        return urlStr
    end

    if urlStr:find("^https?://") then
        local hash = urlHash(urlStr)
        local filePath = "HYPER_Cache/banner_" .. hash .. ".png"
        if _getcustomasset and _isfile and _isfile(filePath) then
            local ok, custom = pcall(function() return _getcustomasset(filePath) end)
            if ok and custom then return custom end
        end

        local ok, data = pcall(function()
            local reqFunc = (request or http_request or (syn and syn.request) or (http and http.request))
            if reqFunc then
                local res = reqFunc({
                    Url = urlStr,
                    Method = "GET",
                    Headers = {
                        ["User-Agent"] = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
                        ["Accept"] = "*/*"
                    }
                })
                if res and (res.StatusCode == 200 or res.Status == 200) and #res.Body > 50 then
                    return res.Body
                end
            end
            if game and game.HttpGet then
                return game:HttpGet(urlStr)
            end
            return nil
        end)

        if ok and data and #data > 50 and _writefile then
            pcall(function()
                if _makefolder and _isfolder and not _isfolder("HYPER_Cache") then
                    _makefolder("HYPER_Cache")
                end
                _writefile(filePath, data)
            end)
            if _getcustomasset then
                local ok2, custom = pcall(function() return _getcustomasset(filePath) end)
                if ok2 and custom then return custom end
            end
        end
    end

    return resolveXinzAsset("banner")
end

