local function createCorner(instance, radius)
    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, radius or 8)
    corner.Parent = instance
    return corner
end

local function createStroke(instance, color, thickness, transparency)
    local stroke = Instance.new("UIStroke")
    stroke.Color = color or Color3.fromRGB(255, 255, 255)
    stroke.Thickness = thickness or 1
    stroke.Transparency = transparency or 0
    stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    stroke.Parent = instance
    return stroke
end

local function makeDraggable(frame, additionalHandles, onDragStarted, onDragEnded)
    local dragging = false
    local dragInput = nil
    local dragStart = Vector3.new()
    local startPos = frame.Position
    local currentTween = nil

    local function getScale()
        local s = frame:FindFirstChildOfClass("UIScale")
        if s and s.Scale > 0 then return s.Scale end
        local p = frame.Parent
        while p do
            local ps = p:FindFirstChildOfClass("UIScale")
            if ps and ps.Scale > 0 then return ps.Scale end
            p = p.Parent
        end
        return 1
    end

    local function update(input)
        if not dragging then return end
        local delta = input.Position - dragStart
        local scale = getScale()
        local targetPos = UDim2.new(
            startPos.X.Scale,
            startPos.X.Offset + (delta.X / scale),
            startPos.Y.Scale,
            startPos.Y.Offset + (delta.Y / scale)
        )
        if currentTween then currentTween:Cancel() end
        currentTween = TweenService:Create(
            frame,
            TweenInfo.new(0.08, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
            { Position = targetPos }
        )
        currentTween:Play()
    end

    local function attachHandle(handle)
        if not handle then return end
        handle.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                if UserInputService:GetFocusedTextBox() ~= nil then return end
                dragging = true
                dragStart = input.Position
                startPos = frame.Position
                if typeof(onDragStarted) == "function" then
                    onDragStarted()
                end
            end
        end)
    end

    attachHandle(frame)
    if additionalHandles then
        for _, h in ipairs(additionalHandles) do
            attachHandle(h)
        end
    end

    frame.InputChanged:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
            dragInput = input
        end
    end)

    UserInputService.InputChanged:Connect(function(input)
        if dragging and (input == dragInput or input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
            update(input)
        end
    end)

    UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            if dragging then
                dragging = false
                if typeof(onDragEnded) == "function" then
                    onDragEnded()
                end
            end
        end
    end)

    return {
        attachHandle = attachHandle
    }
end

-- ==============================================================================
-- // PandaAuth Key Engine & PUSL-V4 Integration (Official pandauth.com SDK)
-- ==============================================================================
local PUSL = nil
local function getPUSL()
    if PUSL and type(PUSL.configure) == "function" then
        return PUSL
    end
    local ok, src = pcall(function()
        if typeof(game) == "Instance" and typeof(game.HttpGet) == "function" then
            return game:HttpGet("https://secure.pandauth.com/pv4/lib")
        end
    end)
    if ok and src and typeof(src) == "string" and #src > 100 then
        local loadOk, lib = pcall(function()
            return loadstring(src)()
        end)
        if loadOk and type(lib) == "table" and type(lib.configure) == "function" then
            PUSL = lib
            pcall(function()
                PUSL.configure({
                    serviceId = Config.PandaServiceId,
                    debug = false,
                    kickOnDetect = false,
                })
            end)
            return PUSL
        end
    end
    return PUSL
end

