task.spawn(function()
    getPUSL()
end)

local function getHWID()
    local hwid = nil
    local lib = getPUSL()
    if lib and typeof(lib.hwid) == "function" then
        local pOk, pHwid = pcall(lib.hwid)
        if pOk and pHwid and typeof(pHwid) == "string" and #pHwid > 0 then
            return pHwid
        end
    end
    pcall(function()
        if typeof(gethwid) == "function" then hwid = gethwid()
        elseif typeof(get_hwid) == "function" then hwid = get_hwid()
        elseif typeof(getexecutorhwid) == "function" then hwid = getexecutorhwid()
        elseif typeof(identifyexecutor) == "function" then
            hwid = tostring(LocalPlayer.UserId) .. "_" .. tostring(identifyexecutor())
        end
    end)
    if not hwid or hwid == "" then
        hwid = tostring(LocalPlayer.UserId) .. "_HYPER_" .. tostring(math.floor(os.time() / 86400))
    end
    return tostring(hwid)
end

local function getPandaGetKeyURL()
    local lib = getPUSL()
    if lib and typeof(lib.getKeyUrl) == "function" then
        local ok, url = pcall(function() return lib.getKeyUrl() end)
        if ok and url and typeof(url) == "string" and #url > 0 then
            return url
        end
    end
    local hwid = getHWID()
    return string.format(
        "https://ads.pandauth.com/getkey/%s?hwid=%s",
        Config.PandaServiceId,
        HttpService:UrlEncode(hwid)
    )
end

local function copyPandaLink(link)
    local copied = false
    local lib = getPUSL()
    if lib and typeof(lib.copyGetKeyUrl) == "function" then
        local ok = pcall(function() lib.copyGetKeyUrl() end)
        if ok then copied = true end
    end
    if typeof(setclipboard) == "function" then
        local ok = pcall(function() setclipboard(link) end)
        if ok then copied = true end
    end
    if not copied and typeof(toclipboard) == "function" then
        local ok = pcall(function() toclipboard(link) end)
        if ok then copied = true end
    end
    if not copied and typeof(syn) == "table" and typeof(syn.write_clipboard) == "function" then
        local ok = pcall(function() syn.write_clipboard(link) end)
        if ok then copied = true end
    end
    if not copied and typeof(Clipboard) == "table" and typeof(Clipboard.set) == "function" then
        local ok = pcall(function() Clipboard.set(link) end)
        if ok then copied = true end
    end
    pcall(function()
        if typeof(openurl) == "function" then
            openurl(link)
        elseif typeof(web_open) == "function" then
            web_open(link)
        end
    end)
    return copied
end

local function verifyPandaKey(key)
    if not key or key == "" then
        return { valid = false, message = "Key cannot be empty" }
    end

    local cleanKey = tostring(key):match("^%s*(.-)%s*$")
    local hwid = getHWID()

    -- Developer / Testing Bypass Key ("TEST")
    if cleanKey:upper() == "TEST" then
        return {
            valid = true,
            message = "Access Granted • Developer Test Key",
            profile = {
                username = (LocalPlayer and LocalPlayer.Name) or "Tester",
                email = "UID: " .. tostring(LocalPlayer and LocalPlayer.UserId or "0") .. " (Dev Pass)",
                avatar_url = "rbxthumb://type=AvatarHeadShot&id=" .. tostring(LocalPlayer and LocalPlayer.UserId or 0) .. "&w=150&h=150"
            }
        }
    end

    -- 1. Official PUSL-V4 Validation
    local lib = getPUSL()
    if lib and typeof(lib.validate) == "function" then
        local pOk, res = pcall(function()
            return lib.validate(cleanKey)
        end)
        if pOk and type(res) == "table" then
            if res.success == true then
                local exp = nil
                pcall(function()
                    if typeof(lib.getExpiryFormatted) == "function" then
                        exp = lib.getExpiryFormatted()
                    end
                end)
                return {
                    valid = true,
                    message = exp and ("Access Granted • Expiry: " .. tostring(exp)) or "Key Verified Successfully!",
                    profile = {
                        username = (LocalPlayer and LocalPlayer.Name) or "User",
                        email = "UID: " .. tostring(LocalPlayer and LocalPlayer.UserId or "0"),
                        avatar_url = "rbxthumb://type=AvatarHeadShot&id=" .. tostring(LocalPlayer and LocalPlayer.UserId or 0) .. "&w=150&h=150"
                    }
                }
            elseif res.error or res.reason then
                local errMsg = res.error or res.reason
                if errMsg == "INVALID_KEY" then
                    errMsg = "Invalid or expired key. Please check again."
                elseif errMsg == "RATE_LIMITED" then
                    errMsg = "Rate limited. Please wait a moment."
                end
                return { valid = false, message = errMsg }
            end
        end
    end

    -- 2. Direct HTTP API Endpoints Fallback
    local requestFunc = (request or http_request or (syn and syn.request) or (http and http.request))
    local endpoints = {
        string.format("https://ads.pandauth.com/api/v1/keys/verify?service=%s&hwid=%s&key=%s", Config.PandaServiceId, HttpService:UrlEncode(hwid), HttpService:UrlEncode(cleanKey)),
        string.format("https://api.pandauth.com/api/v1/keys/verify?service=%s&hwid=%s&key=%s", Config.PandaServiceId, HttpService:UrlEncode(hwid), HttpService:UrlEncode(cleanKey)),
        string.format("https://pandauth.com/api/v1/keys/verify?service=%s&hwid=%s&key=%s", Config.PandaServiceId, HttpService:UrlEncode(hwid), HttpService:UrlEncode(cleanKey)),
        string.format("https://pandadevelopment.net/api/v1/keys/verify?service=%s&hwid=%s&key=%s", Config.PandaServiceId, HttpService:UrlEncode(hwid), HttpService:UrlEncode(cleanKey))
    }

    for _, endpoint in ipairs(endpoints) do
        local ok, res = pcall(function()
            if requestFunc then
                local response = requestFunc({
                    Url = endpoint,
                    Method = "GET",
                    Headers = {
                        ["User-Agent"] = "Singularity-Loader/3.0 (Roblox)",
                        ["Accept"] = "application/json, text/plain, */*"
                    }
                })
                if response and (response.StatusCode == 200 or response.Status == 200) then
                    return response.Body
                end
            end
            return game:HttpGet(endpoint)
        end)

        if ok and res and #res > 0 then
            local jsonOk, data = pcall(function()
                return HttpService:JSONDecode(res)
            end)

            if jsonOk and type(data) == "table" then
                if data.valid == true or data.status == "success" or data.authenticated == true or data.success == true then
                    return {
                        valid = true,
                        message = data.message or "Key Verified Successfully!",
                        profile = data.profile or data.data or {
                            username = (LocalPlayer and LocalPlayer.Name) or "User",
                            email = "UID: " .. tostring(LocalPlayer and LocalPlayer.UserId or "0"),
                            avatar_url = "rbxthumb://type=AvatarHeadShot&id=" .. tostring(LocalPlayer and LocalPlayer.UserId or 0) .. "&w=150&h=150"
                        }
                    }
                elseif data.valid == false or data.status == "error" or data.authenticated == false or data.success == false then
                    return {
                        valid = false,
                        message = data.message or data.error or "Invalid key or HWID mismatch"
                    }
                end
            end

            if not res:find("<html") and not res:find("<!DOCTYPE") and not res:find("<body") then
                local lowerRes = res:lower()
                if lowerRes == "true" or lowerRes == "valid" or lowerRes:find('"valid":%s*true') or lowerRes:find('"authenticated":%s*true') or lowerRes:find('"success":%s*true') then
                    return {
                        valid = true,
                        message = "PandaAuth: License Active",
                        profile = {
                            username = (LocalPlayer and LocalPlayer.Name) or "User",
                            email = "UID: " .. tostring(LocalPlayer and LocalPlayer.UserId or "0"),
                            avatar_url = "rbxthumb://type=AvatarHeadShot&id=" .. tostring(LocalPlayer and LocalPlayer.UserId or 0) .. "&w=150&h=150"
                        }
                    }
                end
            end
        end
    end

    return { valid = false, message = "Could not verify key. Check key validity or connection." }
end

