-- Function to set progress smoothly with File and Function Info
local function updateProgress(percent, duration, statusText, detailText, isError)
    if statusText then
        StatusLabel.Text = statusText
    end
    if detailText then
        DetailLabel.Text = detailText
    end
    if PercentLabel then
        PercentLabel.Text = tostring(math.floor(math.clamp(percent, 0, 1) * 100)) .. "%"
    end
    if isError then
        StatusLabel.TextColor3 = Color3.fromRGB(255, 75, 75)
        DetailLabel.TextColor3 = Color3.fromRGB(255, 120, 120)
        ProgressFill.BackgroundColor3 = Color3.fromRGB(255, 75, 75)
    else
        StatusLabel.TextColor3 = Color3.fromRGB(240, 240, 245)
        DetailLabel.TextColor3 = Color3.fromRGB(150, 155, 170)
        ProgressFill.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
    end

    local tween = TweenService:Create(ProgressFill, TweenInfo.new(duration or 0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
        Size = UDim2.new(math.clamp(percent, 0, 1), 0, 1, 0)
    })
    tween:Play()
    return tween
end

