MacHomeGlow.ImageTransparency = 0.95
MacHomeGlow.ZIndex = 33
MacHomeGlow.Parent = MacHomeBarContainer

local isBarHovered = false
local isWindowDragging = false

local function updateBarStyle()
    if isWindowDragging then
        TweenService:Create(MacHomeBar, TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            Size = UDim2.new(0, 172, 0, 5),
            BackgroundTransparency = 0.20
        }):Play()
        TweenService:Create(barStroke, TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            Transparency = 0.45
        }):Play()
        TweenService:Create(MacHomeGlow, TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            Size = UDim2.new(0, 200, 0, 20),
            ImageTransparency = 0.82
        }):Play()
    elseif isBarHovered then
        TweenService:Create(MacHomeBar, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            Size = UDim2.new(0, 154, 0, 5),
            BackgroundTransparency = 0.35
        }):Play()
        TweenService:Create(barStroke, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            Transparency = 0.65
        }):Play()
        TweenService:Create(MacHomeGlow, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            Size = UDim2.new(0, 180, 0, 18),
            ImageTransparency = 0.90
        }):Play()
    else
        TweenService:Create(MacHomeBar, TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            Size = UDim2.new(0, 136, 0, 4.5),
            BackgroundTransparency = 0.65
        }):Play()
        TweenService:Create(barStroke, TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            Transparency = 0.85
        }):Play()
        TweenService:Create(MacHomeGlow, TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            Size = UDim2.new(0, 160, 0, 16),
            ImageTransparency = 0.95
        }):Play()
    end
end

MacHomeBar.MouseEnter:Connect(function()
    isBarHovered = true
    updateBarStyle()
end)

MacHomeBar.MouseLeave:Connect(function()
    isBarHovered = false
    updateBarStyle()
end)

