-- Shake Jitter & Flash function on Invalid Key (from C++ entry_button.cpp)
local function triggerKeyInvalidAnimation(errMsg)
    KeyStatus.TextColor3 = Color3.fromRGB(255, 80, 80)
    KeyStatus.Text = errMsg or "Invalid key. Please check again."
    TweenService:Create(VerifyBtn, TweenInfo.new(0.1), { BackgroundColor3 = Color3.fromRGB(235, 55, 55) }):Play()
    local currentPos = KeyCard.Position
    task.spawn(function()
        for i = 1, 6 do
            local offset = (i % 2 == 0 and 6 or -6) * (1 - i / 7)
            KeyCard.Position = UDim2.new(currentPos.X.Scale, currentPos.X.Offset + offset, currentPos.Y.Scale, currentPos.Y.Offset)
            task.wait(0.035)
        end
        KeyCard.Position = currentPos
        task.wait(0.8)
        TweenService:Create(VerifyBtn, TweenInfo.new(0.3), { BackgroundColor3 = Color3.fromRGB(0, 122, 255) }):Play()
    end)
end

