local function createSocialIcon(name, assetKey, hoverColor, targetLink)
    local btn = Instance.new("ImageButton")
    btn.Name = name .. "Btn"
    btn.Size = UDim2.new(0, 16, 0, 16)
    btn.BackgroundTransparency = 1
    btn.Image = resolveXinzAsset(assetKey)
    btn.ImageColor3 = Color3.fromRGB(140, 145, 160)
    btn.ScaleType = Enum.ScaleType.Fit
    btn.ZIndex = 25
    btn.Parent = SocialRow

    btn.MouseEnter:Connect(function()
        TweenService:Create(btn, TweenInfo.new(0.18), { ImageColor3 = hoverColor }):Play()
    end)
    btn.MouseLeave:Connect(function()
        TweenService:Create(btn, TweenInfo.new(0.18), { ImageColor3 = Color3.fromRGB(140, 145, 160) }):Play()
    end)
    btn.MouseButton1Click:Connect(function()
        pcall(function()
            if typeof(setclipboard) == "function" then
                setclipboard(targetLink)
                KeyStatus.TextColor3 = Color3.fromRGB(0, 230, 140)
                KeyStatus.Text = name .. " link copied!"
            end
        end)
    end)
    return btn
end

