-- // Payload Executor
-- ==============================================================================
local function executePayload(gameName)
    local target = TargetGames[gameName]
    if not target then
        if gameName == "Universal" or not gameName then
            target = {
                Local = "Scripts/UI.main/UITest.lua",
                Remote = "https://raw.githubusercontent.com/projecthyper10-stack/HYPER-LOADER/refs/heads/main/UI.main/UITest.lua"
            }
        else
            warn("[Singularity Hub] Game not supported: " .. tostring(gameName))
            return false
        end
    end

    local code = nil
    -- 1. Offline local files
    if typeof(isfile) == "function" and typeof(readfile) == "function" then
        local candidates = {
            target.Local,
            "Scripts/UI.main/UITest.lua",
            "UI.main/UITest.lua",
            "Scripts/UITest.lua",
            "UITest.lua",
            "Scripts/" .. tostring(gameName) .. ".lua",
            "M.lua/" .. tostring(gameName) .. ".lua",
            "HYPER_Cache/" .. tostring(gameName) .. ".lua"
        }
        for _, c in ipairs(candidates) do
            if isfile(c) then
                local content = readfile(c)
                if content and #content > 50 then
                    code = content
                    break
                end
            end
        end
    end

    -- 2. Remote endpoint
    if not code and target.Remote then
        pcall(function()
            local req = (request or http_request or (syn and syn.request) or (http and http.request))
            if req then
                local res = req({ Url = target.Remote, Method = "GET" })
                if res and res.StatusCode == 200 and #res.Body > 50 then
                    code = res.Body
                end
            end
            if not code then
                code = game:HttpGet(target.Remote)
            end
        end)
    end

    if code and #code > 50 then
        local fn, err = loadstring(code)
        if fn then
            local okExec, execErr = pcall(fn)
            if not okExec then
                warn("[Singularity Hub] Execution Error: " .. tostring(execErr))
            end
            return okExec
        else
            warn("[Singularity Hub] Compilation Error: " .. tostring(err))
        end
    end

    return false
end

