-- ==============================================================================
-- // Master Loader Flow (Detailed File & Function Loading Progression)
-- ==============================================================================
local function runLoaderSequence(gameName, gameConfig)
    CenterLoader.Visible = true
    if CenterLoader:IsA("CanvasGroup") then CenterLoader.GroupTransparency = 0 end

    if not gameName or not gameConfig then
        gameName = "Universal"
        gameConfig = TargetGames["Universal"] or {
            RequiresKey = false,
            Local = "Scripts/UI.main/UITest.lua",
            Remote = "https://raw.githubusercontent.com/projecthyper10-stack/HYPER-LOADER/refs/heads/main/UI.main/UITest.lua"
        }
        TargetGames[gameName] = gameConfig
    end

    local gameScriptPath = gameConfig.Local or gameConfig.Remote or ("Scripts/M.lua/" .. tostring(gameName) .. ".lua")
    local features = GameFeatureList[gameName] or "Auto Farm • Combat Automation • Visuals & ESP • Teleport & Player"

    -- Step 1: Engine Initialization (0.65s)
    updateProgress(0.15, 0.4, "[Engine] Initializing Core Security & Bypass...", "Hooks: cloneref • gethui • Memory Protections")
    task.wait(0.65)

    -- Step 2: Assets & Logo Cache (0.65s)
    updateProgress(0.35, 0.4, "[Cache] Loading Assets into HYPER_Cache...", "Cached: HYPER.png (19.1 KB High-Res Vector Logo)")
    task.wait(0.65)

    -- Step 3: Game Detection & Config (0.75s)
    if gameName == "Universal" then
        updateProgress(0.55, 0.5, "[Registry] Map Unlisted • Universal Mode", "PlaceId: " .. tostring(PlaceId) .. " | Loading: UITest.lua")
    else
        updateProgress(0.55, 0.5, "[Registry] Config Loaded: " .. tostring(gameName), "PlaceId: " .. tostring(PlaceId) .. " | Security: PandaAuth v1")
    end
    task.wait(0.75)

    -- Step 4: Loading Script Payload (0.85s)
    updateProgress(0.75, 0.5, "[File] Loading: " .. tostring(gameScriptPath), "Compiling script bytecode & resolving dependencies...")
    task.wait(0.85)

    -- Step 5: Mounting Features & Functions (0.85s)
    updateProgress(0.92, 0.5, "[Modules] Activating Functions for " .. tostring(gameName) .. "...", features)
    task.wait(0.85)

    -- Step 6: Complete & Launch (0.7s)
    if gameName == "Universal" then
        updateProgress(1.0, 0.4, "[Ready] Universal UI Suite Loaded Successfully!", "HYPER Suite v2.6 Active • Launching Interface...")
    else
        updateProgress(1.0, 0.4, "[Ready] " .. tostring(gameName) .. " Loaded Successfully!", "HYPER Suite v2.6 Active • Launching Interface...")
    end
    task.wait(0.7)

    -- Smooth Fade Out (HUD, Background Dim & Blur)
    isAnimatingLogo = false
    if LoaderBlur then
        pcall(function()
            TweenService:Create(LoaderBlur, TweenInfo.new(0.35, Enum.EasingStyle.Sine, Enum.EasingDirection.In), {
                Size = 0
            }):Play()
        end)
    end
    if BackgroundDim then
        pcall(function()
            TweenService:Create(BackgroundDim, TweenInfo.new(0.35, Enum.EasingStyle.Sine, Enum.EasingDirection.In), {
                BackgroundTransparency = 1
            }):Play()
        end)
    end
    for i = 0, 15 do
        local alpha = i / 15
        if LogoIcon then LogoIcon.ImageTransparency = alpha end
        if TitleLabel then TitleLabel.TextTransparency = alpha end
        if StatusLabel then StatusLabel.TextTransparency = alpha end
        if DetailLabel then DetailLabel.TextTransparency = alpha end
        if PercentLabel then PercentLabel.TextTransparency = alpha end
        if ProgressTrack then ProgressTrack.BackgroundTransparency = alpha end
        if ProgressFill then ProgressFill.BackgroundTransparency = alpha end
        task.wait(0.02)
    end
    if LoaderBlur then pcall(function() LoaderBlur:Destroy() end) end
    LoaderUI:Destroy()

    -- Execute Script Payload
    executePayload(gameName)
end

