            runLoaderSequence(detectedGameName, gameConfig)
        end

        VerifyBtn.MouseButton1Click:Connect(handleDirectStart)
        UserInputService.InputBegan:Connect(function(input, gpe)
            if not isStarting and not gpe and (input.KeyCode == Enum.KeyCode.Return or input.KeyCode == Enum.KeyCode.KeypadEnter) then
                handleDirectStart()
            end
        end)
        return
    end

    local function handleKeySubmit()
        local key = KeyInputBox.Text:match("^%s*(.-)%s*$")
        if key == "" then
            triggerKeyInvalidAnimation("Please enter your key")
            return
        end

        VerifyBtn.Text = "Verifying..."
        VerifyBtn.Active = false
        KeyStatus.TextColor3 = Color3.fromRGB(200, 205, 220)
        KeyStatus.Text = "Validating with PandaAuth..."

        task.spawn(function()
            local res = verifyPandaKey(key)
            if res and res.valid then
                pcall(function()
                    if typeof(writefile) == "function" then
                        writefile("HyperHubKey.txt", key)
                        writefile("SingularityKey.txt", key)
                    end
                end)

                if res.profile then
                    getgenv().KeyUsername = res.profile.username
                    getgenv().KeyEmail = res.profile.email or ("UID: " .. tostring(LocalPlayer.UserId))
                    getgenv().KeyAvatar = res.profile.avatar_url or ("rbxthumb://type=AvatarHeadShot&id=" .. tostring(LocalPlayer.UserId) .. "&w=150&h=150")
                end

                KeyStatus.TextColor3 = Color3.fromRGB(40, 200, 64)
                KeyStatus.Text = "Access Granted!"
                TweenService:Create(VerifyBtn, TweenInfo.new(0.25), { BackgroundColor3 = Color3.fromRGB(40, 200, 64) }):Play()
                task.wait(0.4)

                -- Smooth fade out KeyCard
                pcall(function()
                    TweenService:Create(KeyCard, TweenInfo.new(0.35, Enum.EasingStyle.Sine, Enum.EasingDirection.In), {
                        BackgroundTransparency = 1
                    }):Play()
                end)
                task.wait(0.35)
                KeyCard.Visible = false
                runLoaderSequence(detectedGameName, gameConfig)
            else
                VerifyBtn.Text = "Enter   →"
                VerifyBtn.Active = true
                triggerKeyInvalidAnimation((res and res.message) or "Invalid key. Please check again.")
            end
        end)
    end

    VerifyBtn.MouseButton1Click:Connect(handleKeySubmit)
    KeyInputBox.FocusLost:Connect(function(enter)
        if enter then handleKeySubmit() end
    end)
end)
